INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'hr-b2g-2019', id, '2019-01-01', 1, 'https://porezna-uprava.gov.hr/en' FROM countries WHERE name_en = 'Croatia';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('hr-b2g-2019', 'en', 'B2G e-invoicing already mandatory', 'Public-sector invoicing has run on structured e-invoicing for years — Fiskalizacija 2.0 extends the same underlying EN 16931 alignment to the much larger domestic B2B and B2C economy.', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'hr-b2b', id, '2026-01-01', 1, 'https://porezna-uprava.gov.hr/en' FROM countries WHERE name_en = 'Croatia';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('hr-b2b', 'en', 'Fiskalizacija 2.0 — mandatory e-invoicing & e-reporting for VAT-registered businesses', 'Croatia''s "Fiscalization 2.0" reform made structured e-invoicing (issuance and receipt) and real-time e-reporting mandatory for all VAT-registered, Croatian-established taxpayers, on top of the B2G e-invoicing mandate already in force since 2019.', '["Register an AMS address and contract a certified information intermediary or access point", "Ensure ERP systems produce valid UBL 2.1 XML aligned with the HR-FISK 2.0 CIUS (including 6-digit KPD codes and OIBs)", "Build in the 5-day buyer-side fiscalization workflow and monthly e-reporting by the 20th", "Archive original XML invoices for 11 years"]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'hr-nonvat', id, '2027-01-01', 0, 'https://porezna-uprava.gov.hr/en' FROM countries WHERE name_en = 'Croatia';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('hr-nonvat', 'en', 'Mandate extends to non-VAT-registered entities and public bodies', 'The obligation to issue (not just receive) structured e-invoices and e-reporting data extends to non-VAT-registered entities — small companies, freelancers, and certain public/budgetary bodies.', '["Non-VAT-registered businesses and sole traders: confirm e-invoicing issuance capability well ahead of this date", "Public bodies not registered for VAT should complete access-point integration during 2026"]');
